(function(root){
'use strict';const H=typeof module!=='undefined'?require('./attendance-model.js'):root.Hive;const copy=x=>JSON.parse(JSON.stringify(x));
function rowOf(s,t){return Math.max(1,Math.ceil((Math.max(Math.abs(s.x+1-t.x-1.5),Math.abs(s.y+1-t.y-1.5))-1.5)/2))}
function position(s,t){return{x:s.x,y:s.y,w:2,h:2,trap:t.id,row:rowOf(s,t)}}
function cityCollisions(s,box,ignoreId){return s.members.filter(m=>m.id!==ignoreId&&m.slot).map(m=>s.slots.find(x=>x.id===m.slot)).filter(Boolean).some(o=>H.overlap(box,o))}
function valid(s,box,ignoreId){return Number.isInteger(box.x)&&Number.isInteger(box.y)&&![...s.traps,...s.structures,...s.blocks].some(o=>H.overlap(box,o))&&!cityCollisions(s,box,ignoreId)}
function move(s,id,x,y){const n=copy(s),m=n.members.find(m=>m.id===id);if(!m)throw Error('Player not found.');if(m.locked)throw Error('This city is locked.');const t=n.traps.find(t=>t.id===m.trap);const box=position({x,y},t);if(!valid(n,box,id))throw Error('That position overlaps a city, trap, structure or blocked terrain.');const old=n.slots.find(s=>s.id===m.slot);if(old&&old.x===x&&old.y===y)return n;const target=n.slots.find(s=>s.trap===m.trap&&s.x===x&&s.y===y&&!n.members.some(p=>p.slot===s.id));const occupiedIds=new Set(n.members.filter(p=>p.id!==id&&p.slot).map(p=>p.slot));n.slots=n.slots.filter(s=>occupiedIds.has(s.id)||s.id===m.slot||s.id===target?.id||!H.overlap(s,box));if(target){m.slot=target.id;n.slots=n.slots.filter(s=>s!==old||s.id===target.id)}else if(old){Object.assign(old,box)}else{let slotId=`city-${id}`,i=1;while(n.slots.some(p=>p.id===slotId))slotId=`city-${id}-${i++}`;const slot={...box,id:slotId};n.slots.push(slot);m.slot=slot.id}m.confirmed=false;m.verified=false;return n}
function contact(a,b){let n=0;if(a.x+a.w===b.x||b.x+b.w===a.x)n+=Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));if(a.y+a.h===b.y||b.y+b.h===a.y)n+=Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x));return n}
function pack(t,count,fixed=[],seed=[],variant=0){const boxes=seed.map(copy),r=Math.max(12,Math.ceil(Math.sqrt(count+seed.length))*2+5),candidates=[];for(let x=t.x-r;x<=t.x+r;x++)for(let y=t.y-r;y<=t.y+r;y++){const a=position({x,y},t);if(!fixed.some(b=>H.overlap(a,b)))candidates.push(a)}for(let i=0;i<count;i++){let best=null,bestScore=Infinity;for(const a of candidates){if(boxes.some(b=>H.overlap(a,b)))continue;const c=H.center(a),tc=H.center(t),rad=Math.max(Math.abs(c.x-tc.x),Math.abs(c.y-tc.y));const edge=boxes.reduce((n,b)=>n+contact(a,b),contact(a,t));const bias=variant===0?a.y*.001+a.x*.0001:variant===1?-a.y*.001-a.x*.0001:variant===2?a.x*.001-a.y*.0001:-a.x*.001+a.y*.0001;const score=rad*12-edge*2+Math.hypot(c.x-tc.x,c.y-tc.y)*.02+bias;if(score<bestScore){best=a;bestScore=score}}if(!best)break;boxes.push(best)}return boxes.slice(seed.length)}
function internalHoles(t,boxes){const all=[t,...boxes],minX=Math.min(...all.map(b=>b.x))-1,maxX=Math.max(...all.map(b=>b.x+b.w))+1,minY=Math.min(...all.map(b=>b.y))-1,maxY=Math.max(...all.map(b=>b.y+b.h))+1,area=(maxX-minX)*(maxY-minY);if(area>10000)return 0;const occupied=new Set();for(const b of all)for(let x=b.x;x<b.x+b.w;x++)for(let y=b.y;y<b.y+b.h;y++)occupied.add(x+','+y);const outside=new Set(),queue=[[minX,minY]];outside.add(minX+','+minY);for(let i=0;i<queue.length;i++){const[x,y]=queue[i];for(const[xx,yy]of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){const key=xx+','+yy;if(xx<minX||xx>=maxX||yy<minY||yy>=maxY||occupied.has(key)||outside.has(key))continue;outside.add(key);queue.push([xx,yy])}}return area-occupied.size-outside.size}
function layoutCost(t,boxes){if(!boxes.length)return 0;const minX=Math.min(t.x,...boxes.map(b=>b.x)),maxX=Math.max(t.x+t.w,...boxes.map(b=>b.x+2)),minY=Math.min(t.y,...boxes.map(b=>b.y)),maxY=Math.max(t.y+t.h,...boxes.map(b=>b.y+2));return internalHoles(t,boxes)*1000+(maxX-minX)*(maxY-minY)*20+boxes.reduce((n,b)=>n+Math.hypot(b.x+1-t.x-1.5,b.y+1-t.y-1.5),0)}
const templateCache=new Map();function template(t,count=60){const key=`${t.id}:${t.x}:${t.y}:${count}`;if(!templateCache.has(key)){let best=null,cost=Infinity;for(let v=0;v<4;v++){const p=pack(t,count,[t],[],v),c=layoutCost(t,p);if(c<cost){best=p;cost=c}}templateCache.set(key,best.map((b,i)=>({...b,id:`default-${t.id}-${i}`})))}return copy(templateCache.get(key))}
function changes(before,after,trap){return before.members.filter(m=>m.trap===trap).flatMap(m=>{const a=before.slots.find(x=>x.id===m.slot),nm=after.members.find(x=>x.id===m.id),b=after.slots.find(x=>x.id===nm.slot);if((a?.x??null)===(b?.x??null)&&(a?.y??null)===(b?.y??null))return[];return[{id:m.id,name:m.name,from:a?{x:a.x,y:a.y,row:a.row}:null,to:b?{x:b.x,y:b.y,row:b.row}:null}]})}
function rebuild(s,trap,reset=false){const n=copy(s),t=n.traps.find(t=>t.id===trap);if(!t)throw Error('Select one Bear Trap.');const selected=n.members.filter(m=>m.trap===trap),locked=selected.filter(m=>m.locked&&m.slot).map(m=>n.slots.find(x=>x.id===m.slot)).filter(Boolean),outside=n.members.filter(m=>m.trap!==trap&&m.slot).map(m=>n.slots.find(x=>x.id===m.slot)).filter(Boolean),hard=[...n.traps,...n.blocks,...n.structures,...outside,...locked];const moving=selected.filter(m=>!m.locked&&(reset||m.slot));let blocked=0,positions=[];
if(reset){const normal=template(t);positions=normal.filter(a=>{const hit=hard.some(b=>H.overlap(a,b));if(hit)blocked++;return!hit})}else{let bestCost=Infinity;for(let v=0;v<4;v++){const p=pack(t,moving.length,hard,locked,v),cost=layoutCost(t,[...locked,...p]);if(p.length>=positions.length&&cost<bestCost){positions=p;bestCost=cost}}}
const oldSlots=new Map(n.slots.map(x=>[x.id,copy(x)]));const newSlots=reset?n.slots.filter(x=>x.trap!==trap||locked.some(b=>b.id===x.id)):n.slots.filter(x=>!selected.some(m=>!m.locked&&m.slot===x.id));if(reset){const ids=new Set(newSlots.map(p=>p.id));positions.forEach(p=>{const original=p.id;let i=1;while(ids.has(p.id))p.id=original+'-'+i++;ids.add(p.id);newSlots.push(p)})}
const order=moving.sort((a,b)=>{const aa=oldSlots.get(a.slot),bb=oldSlots.get(b.slot);const distance=o=>o?Math.hypot(o.x-t.x,o.y-t.y):999;return distance(aa)-distance(bb)||H.attendanceScore(n,b,trap)-H.attendanceScore(n,a,trap)||a.name.localeCompare(b.name)});const available=[...positions];for(const m of order){const old=oldSlots.get(m.slot);available.sort((a,b)=>{const score=p=>p.row*100+(old?Math.hypot(p.x-old.x,p.y-old.y):0)*.1;return score(a)-score(b)});const p=available.shift();if(p){if(reset)m.slot=p.id;else{const slot={...p,id:m.slot||`city-${m.id}`};newSlots.push(slot);m.slot=slot.id}}else m.slot=null;const next=newSlots.find(x=>x.id===m.slot);if(!old||!next||old.x!==next.x||old.y!==next.y){m.confirmed=false;m.verified=false}}
if(!reset){const occupied=newSlots.filter(x=>n.members.some(m=>m.slot===x.id));n.slots=newSlots.filter(x=>occupied.some(p=>p.id===x.id)||!occupied.some(p=>H.overlap(x,p)))}else n.slots=newSlots;
return{state:n,changes:changes(s,n,trap),blocked,unassigned:moving.filter(m=>!m.slot).length,notes:blocked?`${blocked} default spots conflict with terrain, structures or fixed cities. These constraints were kept.`:locked.length?'Locked cities were preserved. They can prevent closing every gap.':'Terrain and fixed structures are preserved. This grid heuristic may leave gaps; it does not prove every remaining gap unavoidable.'}}
function assign(s,filter='all'){const n=copy(s),affected=m=>filter==='all'||String(m.trap)===String(filter),occupied=new Set(n.members.filter(m=>m.slot&&(!affected(m)||m.locked)).map(m=>m.slot)),list=n.members.filter(m=>affected(m)&&!m.locked).sort((a,b)=>H.attendanceScore(s,b,b.trap)-H.attendanceScore(s,a,a.trap)||b.priority-a.priority||a.name.localeCompare(b.name));const changes=[];for(const m of list){const old=m.slot;const available=n.slots.filter(p=>p.trap===m.trap&&!occupied.has(p.id)&&![...n.traps,...n.blocks,...n.structures].some(b=>H.overlap(p,b)));available.sort((a,b)=>a.row-b.row||(a.id===old?-1:b.id===old?1:0)||Math.hypot(a.x-n.traps.find(t=>t.id===m.trap).x,a.y-n.traps.find(t=>t.id===m.trap).y)-Math.hypot(b.x-n.traps.find(t=>t.id===m.trap).x,b.y-n.traps.find(t=>t.id===m.trap).y));m.slot=available[0]?.id||null;if(m.slot)occupied.add(m.slot);if(old!==m.slot){m.confirmed=false;m.verified=false;changes.push({id:m.id,name:m.name,old,slot:m.slot,reason:'Attendance priority; existing geometry preserved.'})}}return{members:n.members,changes}}
const priorDemo=H.demo;H.demo=function(){const s=priorDemo();for(const t of s.traps){const slots=template(t);const ms=s.members.filter(m=>m.trap===t.id);s.slots=s.slots.filter(p=>p.trap!==t.id).concat(slots);ms.forEach((m,i)=>m.slot=slots[i].id)}return s};
Object.assign(H,{cityRow:rowOf,validCityPosition:valid,moveCity:move,defaultCityTemplate:template,compactLayout:(s,t)=>rebuild(s,t,false),resetLayout:(s,t)=>rebuild(s,t,true),suggest:assign});if(typeof module!=='undefined')module.exports=H;
})(typeof window!=='undefined'?window:globalThis);
